     input
         .parse::<i32>()
         .map_err(Error::Indivisible)
         .map(|v| v % 3)
         .and_then(|remainder| {
             if remainder == 0 {
                 Ok(())
             } else {
                 Err(Error::Remainder(remainder as u8))
             }
         })
 }
 ```
